-- Know UAV: add lesson 1-7 (أنظمة الدرون في السعودية). Paste into Supabase SQL Editor and Run.
insert into public.lessons (id,level,ord,title,hook,mins,is_free,body,scenes,quiz,audio_url) values ('1-7',1,7,'أنظمة الدرون في السعودية','قبل ما تطيّر درون حقيقية برّا المحاكي، اعرف وش يطلب منك النظام.',6,false,'[["p","الجهة المنظِّمة لتشغيل الطائرات بدون طيار في المملكة هي <b>الهيئة العامة للطيران المدني</b>. هذا ملخّص عام لأهم ما تحتاج تعرفه قبل أن تطيّر طائرة حقيقية:"],["ul",["<b>تسجيل الطائرة:</b> عبر بوابة الطائرات بدون طيار التابعة للهيئة <span class=\"en\">uas.gaca.gov.sa</span>: الدخول بالنفاذ الوطني، ثم إنشاء ملفك، ثم إضافة طائرة جديدة واختيار فئة التشغيل.","<b>شهادة الطيار عن بعد:</b> تُطلب من البوابة نفسها، وتتضمن اختبار معرفة إلكترونياً.","<b>مدى الرؤية:</b> أبقِ الطائرة في مدى نظرك بالعين المجردة <span class=\"en\">VLOS</span>، وطِر نهاراً وفي طقس مناسب.","<b>الارتفاع:</b> الحد المتعارف عليه نحو ١٢٠ متراً (٤٠٠ قدم) فوق سطح الأرض، ما لم يُصرَّح بغير ذلك.","<b>المناطق الممنوعة دون تصريح:</b> المطارات ومحيطها، والتجمعات، والمنشآت الحكومية والحساسة.","<b>الخصوصية:</b> لا تصوّر الأشخاص أو الممتلكات الخاصة دون إذن.","<b>المخالفات:</b> قد تؤدي إلى غرامات ومصادرة الطائرة."]],["p","التدريب في المحاكي لا يحتاج أي تسجيل، وهو أفضل مكان تبني فيه مهارتك قبل الطيران الحقيقي."],["tip","هذا الدرس تعليمي عام وليس استشارة نظامية. الأنظمة والإجراءات تتحدث، فارجع دائماً لبوابة الهيئة العامة للطيران المدني قبل أي طيران. آخر مراجعة: أكتوبر ٢٠٢٦."]]'::jsonb,'[{"v":"title","cap":"أنظمة الدرون في السعودية","say":"في هالدرس بنعرف وش يطلب منك النظام في السعودية قبل ما تطيّر درون حقيقية. والجهة المسؤولة هي الهيئة العامة للطيران المدني."},{"v":"reg","cap":"سجّل طيارتك في بوابة الهيئة","say":"أول خطوة: تسجّل طيارتك في بوابة الطائرات بدون طيار التابعة للهيئة. تدخل بالنفاذ الوطني، تسوي ملفك، وتضيف طيارتك وتختار فئة التشغيل."},{"v":"rpc","cap":"شهادة الطيار عن بعد","say":"وبعدها تطلب شهادة الطيار عن بعد من نفس البوابة، وفيها اختبار معرفة إلكتروني. يعني اللي تتعلمه هنا بيفيدك فيه."},{"v":"vlos","cap":"خلها في مدى عينك","say":"وأثناء الطيران: خل الطيارة في مدى نظرك بالعين المجردة، وطيّر بالنهار وفي جو مناسب."},{"v":"alt120","cap":"الارتفاع: الحد المتعارف عليه ١٢٠ م","say":"ولا ترتفع فوق الحد المسموح. الحد المتعارف عليه مية وعشرين متر تقريباً، إلا إذا عندك تصريح."},{"v":"nofly","cap":"بعيد عن المطارات والتجمعات والمنشآت الحساسة","say":"وابعد عن المطارات والتجمعات والمنشآت الحكومية والحساسة. هذي مناطق ما تطير فيها بدون تصريح."},{"v":"privacy","cap":"احترم خصوصية الناس","say":"واحترم خصوصية الناس: لا تصوّر أحد ولا بيوت الناس بدون إذنهم."},{"v":"points","cap":"تذكّر","pts":["المحاكي ما يحتاج تسجيل","الدرون الحقيقية: سجّل قبل ما تطير","المرجع الرسمي: بوابة الهيئة"],"say":"وتذكّر: التدريب في المحاكي ما يحتاج تسجيل، لكن الدرون الحقيقية لازم تسجّلها. والأنظمة تتحدث، فدايم ارجع لبوابة الهيئة قبل أي طيران."}]'::jsonb,'[{"q":"ما الجهة التي تنظّم تشغيل الطائرات بدون طيار في المملكة؟","o":["البلدية","الهيئة العامة للطيران المدني","وزارة الإعلام"],"a":1,"w":"الهيئة العامة للطيران المدني هي الجهة المنظِّمة."},{"q":"أين تسجّل طائرتك؟","o":["في المتجر اللي اشتريتها منه","في بوابة الطائرات بدون طيار التابعة للهيئة","ما تحتاج تسجيل"],"a":1,"w":"التسجيل عبر بوابة الهيئة uas.gaca.gov.sa بالدخول بالنفاذ الوطني."},{"q":"أي مكان تتجنب الطيران فيه دون تصريح؟","o":["أرض فضاء بعيدة","محيط المطار","ميدان تدريب مصرّح"],"a":1,"w":"المطارات ومحيطها مناطق ممنوعة دون تصريح."},{"q":"هل التدريب في المحاكي يحتاج تسجيلاً؟","o":["نعم","لا، التسجيل للطائرة الحقيقية"],"a":1,"w":"المحاكي لا يحتاج تسجيلاً، الطائرة الحقيقية هي اللي تُسجَّل."}]'::jsonb,'/assets/audio/1-7.mp3')
on conflict (id) do update set level=excluded.level, ord=excluded.ord, title=excluded.title, hook=excluded.hook, mins=excluded.mins, is_free=excluded.is_free, body=excluded.body, scenes=excluded.scenes, quiz=excluded.quiz, audio_url=coalesce(excluded.audio_url, public.lessons.audio_url);
